INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32611, 'Revelation 18:19', 'Revelation', 18, 19, 'هغوی په خپلو سرونو باندې خاورې بادولې او ژړاګانې او ویر یې کاوه او ویل یې: افسوس، افسوس، په دې لوی ښار چې شتمن شول د هغې په وسیله ټول خاوندان د کشتۍ‌ګانو شو برباد په یو ساعت کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_19.mp3', '', 1761754199, 1761754199),
(32612, 'Revelation 18:20', 'Revelation', 18, 20, 'ای اسمانه، خوشحالي وکړه، ای د خدای سپېڅلو خلکو، ای رسولانو او پیغمبرانو، شئ خوشحاله په هغې باندې، ځکه چې ستاسو په خاطر خدای قضاوت کړی هغې باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_20.mp3', '', 1761754199, 1761754199),
(32613, 'Revelation 18:21', 'Revelation', 18, 21, 'په دې وخت کې یوې زورورې فرښتې یوه تیږه چې د ژرندې د یو غټ پل په شان وه، راواخیستله او بحر ته یې ګوزاره کړه او ویې ویل: په همدې ډول به بابل هغه لوی ښار هم به ګوزار کړای شي په زوره ښکته او بیا به هم هېڅکله ونه لیدل شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_21.mp3', '', 1761754199, 1761754199),
(32614, 'Revelation 18:22', 'Revelation', 18, 22, 'نور به هېڅکله هم وانه ورېدل شي تا کې اوازونه د چنګ غږوونکو، ساز غږوونکو، شپېلۍ وهونکو او سرني وهونکو نه به پیدا شي تا کې کوم کسبګر چې کاروبار کوي او نه به بیا واورېدل شي تا کې اواز د ژرندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_22.mp3', '', 1761754199, 1761754199),
(32615, 'Revelation 18:23', 'Revelation', 18, 23, 'نور به ونه ولیدل شي تا کې د څراغ رڼا او نه به واورېدل شي تا کې اوازونه د زوم او ناوې ځکه چې ستا سوداګران ډېر قدرتمند خلک وو د نړۍ د ټولو سوداګرانو څخه او ټول قومونه غولولي وو تا خپلې جادو باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_23.mp3', '', 1761754199, 1761754199),
(32616, 'Revelation 18:24', 'Revelation', 18, 24, 'ستا په کوڅو کې بهېدلې وینې د پیغمبرانو او د خدای د خلکو او د هغو ټولو خلکو خون چې وژل شوي دي د ځمکې په مخ دی ستا په غاړه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_24.mp3', '', 1761754199, 1761754199),
(32617, 'Matthew 4:1', 'Matthew', 4, 1, 'بیا روح القدس عیسی دښتې ته بوته چې د شیطان له خوا وازمایل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_1.mp3', '', 1761754199, 1761754199),
(32618, 'Matthew 4:2', 'Matthew', 4, 2, 'عیسی څلوېښت ورځې او څلوېښت شپې روژه ونیوله او په پای کې وږی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_2.mp3', '', 1761754199, 1761754199),
(32619, 'Matthew 4:3', 'Matthew', 4, 3, 'بیا شیطان ورنژدې شو او ورته ویې ویل: «که ته د خدای زوی یې، نو دې تیږو ته ووایه چې په ډوډۍ باندې بدلې شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_3.mp3', '', 1761754199, 1761754199),
(32620, 'Matthew 4:4', 'Matthew', 4, 4, 'خو عیسی په ځواب کې وویل: «د خدای په کلام کې لیکل شوي دي: انسان یوازې په ډوډۍ نه، بلکې په هرې یوې خبرې باندې ژوندی دی چې د خدای د خولې څخه راوځي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_4.mp3', '', 1761754199, 1761754199),
(32621, 'Matthew 4:5', 'Matthew', 4, 5, 'بیا شیطان هغه سپېڅلي ښار اورشلیم ته بوته او د خدای د کور په مناره باندې یې ودراوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_5.mp3', '', 1761754199, 1761754199),
(32622, 'Matthew 4:6', 'Matthew', 4, 6, 'او ورته ویې ویل: «که ته د خدای زوی یې، نو خپل ځان ښکته وغورځوه، ځکه چې د خدای په کلام کې لیکل شوي دي: هغه به ستا دپاره فرښتو ته حکم وکړي او هغوی به تا په خپلو لاسونو کې پورته کړي، ترڅو پښه دې په تیږه ونه لګیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_6.mp3', '', 1761754199, 1761754199),
(32623, 'Matthew 4:7', 'Matthew', 4, 7, 'عیسی ځواب ورکړ: «د خدای په کلام کې دا هم لیکل شوي دي: خپل څښتن خدای مه ازمایئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_7.mp3', '', 1761754199, 1761754199),
(32624, 'Matthew 4:8', 'Matthew', 4, 8, 'بیا شیطان هغه یو ډېر لوړ غره ته وخېژاوه او د نړۍ ټولې پاچاهۍ او د هغوی شان او شوکت یې ورته وښود', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_8.mp3', '', 1761754199, 1761754199),
(32625, 'Matthew 4:9', 'Matthew', 4, 9, 'او ورته ویې ویل: «که ته ماته سجده وکړې او زما عبادت وکړې نو دا ټول به تاته درکړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_9.mp3', '', 1761754199, 1761754199),
(32626, 'Matthew 4:10', 'Matthew', 4, 10, 'بیا عیسی هغه ته وویل: «ورک شه شیطانه! ځکه چې د خدای په کلام کې لیکل شوي دي: خپل څښتن خدای ته عبادت کوه او یوازې د هغه خدمت کوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_10.mp3', '', 1761754199, 1761754199),
(32627, 'Matthew 4:11', 'Matthew', 4, 11, 'نو شیطان هغه پرېښود او فرښتې د هغه په خدمت کې حاضرې شوې. عیسی په جلیل کې خپل کار پیل کوي (مرقوس ۱‏:‌۱۴‌‏-‌۱۵ او لوقا ۴‏:‌۱۴‌‏-‌۱۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_11.mp3', '', 1761754199, 1761754199),
(32628, 'Matthew 4:12', 'Matthew', 4, 12, 'کله چې عیسی واورېدل چې یحیی په زندان کې اچول شوی دی، نو هغه جلیل ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_12.mp3', '', 1761754199, 1761754199),
(32629, 'Matthew 4:13', 'Matthew', 4, 13, 'هغه په ناصرې کې پاتې نه شو او کپرناحوم ته چې د جلیل د بحیرې په غاړه د زبولون او نفتالي په سیمه کې پروت دی، لاړ او هلته پاتې شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_13.mp3', '', 1761754199, 1761754199),
(32630, 'Matthew 4:14', 'Matthew', 4, 14, 'ترڅو هغه خبرې چې خدای د اشعیا نبي په وسیله کړې وې رښتیا شي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_14.mp3', '', 1761754199, 1761754199),
(32631, 'Matthew 4:15', 'Matthew', 4, 15, 'د زبولون او نفتالي سیمې د بحیرې په غاړه او د اردن د سیند بلې غاړې ته پرتې دي. یعنې د جلیل په سیمه کې چې غیریهودیان په کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_15.mp3', '', 1761754199, 1761754199),
(32632, 'Matthew 4:16', 'Matthew', 4, 16, 'کوم خلک چې په تیارو کې اوسیږي هغوی به یوه لویه رڼا وویني او په هغو خلکو باندې به چې د مرګ په سیوری کې اوسیږي د سهار رڼایي وځلیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_16.mp3', '', 1761754199, 1761754199),
(32633, 'Matthew 4:17', 'Matthew', 4, 17, 'د هماغه وخت نه عیسی دا وعظ پیل کړ: «توبه‌ګار شئ، ځکه چې اسماني پاچاهي رانژدې شوې ده.» عیسی څلورو ماهيګیرو ته بلنه ورکوي (مرقوس ۱‏:‌۱۶‌‏-‌۲۰ او لوقا ۵‏:‌۱‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_17.mp3', '', 1761754199, 1761754199),
(32634, 'Matthew 4:18', 'Matthew', 4, 18, 'کله چې عیسی د جلیل د بحیرې په غاړه ګرځېده، نو دوه ورونه یې ولیدل چې یو یې شمعون ؤ چې د پطروس په نوم هم یادېده او بل د هغه ورور اندریاس ؤ. هغوی په بحیرې کې جال اچاوه، ځکه چې هغوی ماهیګیران وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_18.mp3', '', 1761754199, 1761754199),
(32635, 'Matthew 4:19', 'Matthew', 4, 19, 'عیسی هغوی ته وویل: «ما پسې راځئ او زه به تاسو ته وښایم چې څنګه د ماهیانو په ځای انسانان ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_19.mp3', '', 1761754199, 1761754199),
(32636, 'Matthew 4:20', 'Matthew', 4, 20, 'هغوی سمدلاسه خپل جالونه پرېښودل او هغه پسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_20.mp3', '', 1761754199, 1761754199),
(32637, 'Matthew 4:21', 'Matthew', 4, 21, 'عیسی له هغه ځای څخه روان شو او دوه نور کسان یې ولیدل چې سره ورونه وو چې یعقوب او یوحنا نومېدل او د زبدي زامن وو. هغوی د خپل پلار سره په کشتۍ کې جالونه تیارول. عیسی هغوی راوغوښتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_21.mp3', '', 1761754199, 1761754199),
(32638, 'Matthew 4:22', 'Matthew', 4, 22, 'هغوی سمدلاسه خپل پلار او کشتۍ پرېښودل او په هغه پسې روان شول. عیسی تعلیم ورکوي، وعظ کوي او ناروغانو ته شفا ورکوي (لوقا ۶‏:‌۱۷‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_22.mp3', '', 1761754199, 1761754199),
(32639, 'Matthew 4:23', 'Matthew', 4, 23, 'عیسی په ټول جلیل کې ګرځېده، د هغوی په کنیسو کې یې تعلیم ورکاوه او د خدای د پاچاهۍ زېری یې خپراوه او خلکو ته یې د هر ډول ناروغیو او رنځونو څخه شفا ورکوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_23.mp3', '', 1761754199, 1761754199),
(32640, 'Matthew 4:24', 'Matthew', 4, 24, 'نو هغه په ټوله سوریه کې مشهور شو او خلکو به ټول هغه کسان چې په ډول ډول ناروغیو او دردونو باندې اخته وو او هغه خلک چې پېریانو نیولي وو، میرګي یې درلودل او یا ګوډان او شلان وو، هغه ته راوستل او هغه به روغول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_24.mp3', '', 1761754199, 1761754199),
(32641, 'Matthew 4:25', 'Matthew', 4, 25, 'ګڼ شمېر خلک د جلیل، دکاپولس، اورشلیم، یهودیې او د اردن د سیند د بلې غاړې د سیمې خلک ورپسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew4_verse_25.mp3', '', 1761754199, 1761754199),
(32642, 'Hebrews 4:1', 'Hebrews', 4, 1, 'څرنګه چې د خدای ارامۍ ته د وردننه کېدلو په هکله د هغه وعده لا تر‌اوسه په خپل حال پاتې ده، نو باید پام وکړو، هسې نه چې په تاسو کې کوم څوک هغې ته په رسېدلو کې ناکام شوی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_1.mp3', '', 1761754199, 1761754199),
(32643, 'Hebrews 4:2', 'Hebrews', 4, 2, 'دا زېری چې مونږ واورېد، هغوی هم اورېدلی ؤ، خو هغه پیغام چې هغوی واورېد، هغوی ته یې ګټه ونه رسوله، ځکه چې هغه پیغام یې په ایماندارۍ سره قبول نه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_2.mp3', '', 1761754199, 1761754199),
(32644, 'Hebrews 4:3', 'Hebrews', 4, 3, 'خو مونږ چې ایمان لرو، کولای شو د هغه ارامۍ ته ورننوځو. خو د دې نورو په هکله خدای وویل: «ما د خپل قهر په حال کې وخوړ قسم داخل به نه شي دوی هېڅکله هغه ځای ته چېرته چې زه به ورکومه ارامي ورته» که څه هم د خدای کار د کایناتو د پیدایښت په اړه پای ته رسېدلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_3.mp3', '', 1761754199, 1761754199),
(32645, 'Hebrews 4:4', 'Hebrews', 4, 4, 'ځکه چې د خدای د کلام په یو ځای کې د اوومې ورځې په هکله داسې لیکل شوي دي: «په اوومه ورځ خدای خپل ټول کارونه خلاص کړل او ارام یې وکړ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_4.mp3', '', 1761754199, 1761754199),
(32646, 'Hebrews 4:5', 'Hebrews', 4, 5, 'او په همدې ځای کې خدای یوځل بیا وایي: «داخل به نه شي دوی هېڅکله هغه ځای ته چېرته چې زه به ورکومه ارامي ورته»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_5.mp3', '', 1761754199, 1761754199),
(32647, 'Hebrews 4:6', 'Hebrews', 4, 6, 'نو ځینې خلک دا موقعه لري چې هغه ارامۍ ته وردننه شي، خو هغوی چې اول یې دا زېری واورېد، وردننه نه شول ځکه چې سرغړونه یې وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_6.mp3', '', 1761754199, 1761754199),
(32648, 'Hebrews 4:7', 'Hebrews', 4, 7, 'نو بیا خدای یوه بله ځانګړې ورځ یعنې «نن ورځ» ټاکي، ځکه چې وروسته له ډېرې مودې هغه د داود په وسیله خبرې کړې وې او لکه څنګه چې مخکې ویل شوي وو: «که چېرې نن تاسو اواز واورئ د خدای نو مه سختوئ خپل زړونه»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_7.mp3', '', 1761754199, 1761754199),
(32649, 'Hebrews 4:8', 'Hebrews', 4, 8, 'که چېرې یوشع کولای شوی هغو خلکو ته هغه ارامي ورکړي، نو خدای به وروسته د بلې ورځې په هکله خبرې نه وای کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_8.mp3', '', 1761754199, 1761754199),
(32650, 'Hebrews 4:9', 'Hebrews', 4, 9, 'نو بیا د خدای د خلکو دپاره د سبت ارامي تر‌اوسه هم په خپل حال پاتې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_9.mp3', '', 1761754199, 1761754199),
(32651, 'Hebrews 4:10', 'Hebrews', 4, 10, 'ځکه کومو خلکو چې هغه ارامي موندلې ده چې خدای یې وعده کړې وه، نو د خپلو کارونو څخه به هم ارام ومومي، لکه څنګه چې خدای د خپلو کارونو څخه وموند.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_10.mp3', '', 1761754199, 1761754199),
(32652, 'Hebrews 4:11', 'Hebrews', 4, 11, 'نو راځئ چې ډېر کوښښ وکړو چې هغه ارامي تر‌لاسه کړو. خو که چېرې مونږ سرغړونه وکړو لکه څنګه چې د اسراییلو خلکو کړې وه، نو مونږ به هم ناکام شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_11.mp3', '', 1761754199, 1761754199),
(32653, 'Hebrews 4:12', 'Hebrews', 4, 12, 'ځکه چې د خدای کلام ژوندی او اغېزناک دی او د هرې دوه‌مخې تورې نه ډېر تېره دی. هغه د انسان روح او نفس، بندونو او د هډوکو مغزو ته ورننوځي او د انسان نیت او د زړه خیالونه ښکاره کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_12.mp3', '', 1761754199, 1761754199),
(32654, 'Hebrews 4:13', 'Hebrews', 4, 13, 'په ټولو مخلوقاتو کې هېڅ شی د خدای د نظر څخه پټ نه دی. ټول شیان د هغه د سترګو په وړاندې لوڅ او ښکاره پراته دي او مونږ ټول باید هغه ته حساب ورکړو. عیسی زمونږ ډېر لوی کاهن دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_13.mp3', '', 1761754199, 1761754199),
(32655, 'Hebrews 4:14', 'Hebrews', 4, 14, 'نو څرنګه چې مونږ ډېر لوی کاهن لرو چې اسمانونو ته پورته شوی دی یعنې عیسی چې د خدای زوی دی، نو راځئ چې د خپل ایمان په اقرار باندې ټینګ پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_14.mp3', '', 1761754199, 1761754199),
(32656, 'Hebrews 4:15', 'Hebrews', 4, 15, 'ځکه چې زمونږ لوی کاهن داسې نه دی چې زمونږ په کمزورتیاوو کې زمونږ سره خواخوږي ونه کړي بلکې هغه زمونږ په شان په هر شي کې وازمایل شو، خو ګناه یې ونه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_15.mp3', '', 1761754199, 1761754199),
(32657, 'Hebrews 4:16', 'Hebrews', 4, 16, 'نو راځئ چې په پوره باور سره د خدای د فضل تخت ته ورنژدې شو، ترڅو رحم ومومو او د اړتیا په وخت کې د هغه فضل حاصل کړو ترڅو زمونږ سره مرسته وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews4_verse_16.mp3', '', 1761754199, 1761754199),
(32658, 'Revelation 8:1', 'Revelation', 8, 1, 'کله چې وري اووم مهر مات کړ، نو د نیم ساعت دپاره په اسمان کې کراره کراري وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_1.mp3', '', 1761754199, 1761754199),
(32659, 'Revelation 8:2', 'Revelation', 8, 2, 'بیا ما اووه فرښتې ولیدلې چې د خدای په مخکې ولاړې وې او هغوی ته اووه سرني ورکړل شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_2.mp3', '', 1761754199, 1761754199),
(32660, 'Revelation 8:3', 'Revelation', 8, 3, 'بیا یوه بله فرښته چې د خوشبویي د سوځولو د سرو زرو لوښی ورسره ؤ، راغله او د قربانۍ د ځای سره ودرېدله. هغې ته ډېره زیاته خوشبویي ورکړل شوه چې د خدای د خلکو په دعا سره یې د سرو زرو د قربانۍ په ځای باندې چې د تخت په مخکې وه، وړاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_3.mp3', '', 1761754199, 1761754199),
(32661, 'Revelation 8:4', 'Revelation', 8, 4, 'د خوشبویۍ لوګی د خدای د خلکو په دعا سره د فرښتې د لاس نه پورته د خدای حضور ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_4.mp3', '', 1761754199, 1761754199),
(32662, 'Revelation 8:5', 'Revelation', 8, 5, 'بیا فرښتې هغه د خوشبویۍ لوښی راواخیست او د قربانۍ د ځای د اور نه یې ډک کړ او په ځمکه یې راګوزار کړ. بیا د تندر غږ، غړمبار، برېښنا او زلزله راغله. د سرنیو اوازونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_5.mp3', '', 1761754199, 1761754199),
(32663, 'Revelation 8:6', 'Revelation', 8, 6, 'بیا هغه اووه فرښتې چې اووه سرني ورسره وو، د سرنیو وهلو ته تیارې شولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_6.mp3', '', 1761754199, 1761754199),
(32664, 'Revelation 8:7', 'Revelation', 8, 7, 'کله چې لومړنۍ فرښتې خپل سرنی وواهه، نو اور او ږلۍ د وینې سره په ځمکه راوورېدلې او د ځمکې درېمه برخه او د ونو درېمه برخه یې وسوځوله او ټول شنه واښه وسوځېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_7.mp3', '', 1761754199, 1761754199),
(32665, 'Revelation 8:8', 'Revelation', 8, 8, 'بیا دوهمې فرښتې خپل سرنی وواهه او لکه د یو لوی غره په شان یو شی چې اور ورباندې بل ؤ، بحر ته وغورځول شو او د بحر درېمه برخه په وینو بدله شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_8.mp3', '', 1761754199, 1761754199),
(32666, 'Revelation 8:9', 'Revelation', 8, 9, 'په بحر کې درېمه برخه ژوندي مخلوقات مړه شول او د کشتۍ‌ګانو درېمه برخه په بحر کې له منځه لاړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_9.mp3', '', 1761754199, 1761754199),
(32667, 'Revelation 8:10', 'Revelation', 8, 10, 'بیا درېمې فرښتې خپل سرنی وواهه نو د اسمان نه یو غټ ستوری چې د څراغ په شان بلېده، د سیندونو او چینو په درېمه برخه باندې راولوېد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_10.mp3', '', 1761754199, 1761754199),
(32668, 'Revelation 8:11', 'Revelation', 8, 11, 'د هغه ستوري نوم افسنتین دی چې د تریخ‌والي معنی لري او د اوبو درېمه برخه ترخې شوې او ډېر خلک د دې ترخو اوبو د څښلو له امله مړه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_11.mp3', '', 1761754199, 1761754199),
(32669, 'Revelation 8:12', 'Revelation', 8, 12, 'بیا څلورمې فرښتې خپل سرنی وواهه، نو د لمر، سپوږمۍ او ستورو درېمه برخه یې داسې ووهله چې د هغو درېمه برخه تیاره شوه او د ورځې د رڼا او د شپې د رڼا درېمه برخه له منځه لاړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_12.mp3', '', 1761754199, 1761754199),
(32670, 'Revelation 8:13', 'Revelation', 8, 13, 'بیا مې کتل او د یو عقاب اواز مې واورېد چې په اسمان کې الوته او په لوړ اواز یې ویل: «بلا، بلا او بلا د ځمکې په اوسېدونکو باندې، ځکه چې اوس به درې نورې فرښتې خپل سرني ووهي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation8_verse_13.mp3', '', 1761754199, 1761754199),
(32671, 'Hebrews 13:1', 'Hebrews', 13, 1, 'د خویندو او ورونو په شان یو د بل سره مینه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_1.mp3', '', 1761754199, 1761754199),
(32672, 'Hebrews 13:2', 'Hebrews', 13, 2, 'دا مه هېروئ چې باید د مسافرو مېلمه‌پالنه وکړئ، ځکه چې ځینو خلکو داسې کړي دي او هغوی د فرښتو مېلمه‌پالنه کړې ده که څه هم هغوی یې نه دي پېژندلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_2.mp3', '', 1761754199, 1761754199),
(32673, 'Hebrews 13:3', 'Hebrews', 13, 3, 'هغه کسان چې په زندان کې دي داسې یادوئ لکه چې تاسو ورسره په زندان کې یئ. هغه کسان در په یادوئ چې ظلم ورسره کیږي، نو داسې وګڼئ لکه تاسو چې کړاوونه وینئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_3.mp3', '', 1761754199, 1761754199),
(32674, 'Hebrews 13:4', 'Hebrews', 13, 4, 'ټول باید واده ته درناوی ولري او ښځې او مېړونه باید یو بل ته وفادار اوسي، ځکه چې خدای به بد‌اخلاقه او زناکاره خلک محکوم کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_4.mp3', '', 1761754199, 1761754199),
(32675, 'Hebrews 13:5', 'Hebrews', 13, 5, 'په خپل ژوند کې د پیسو سره د مینې کولو نه ځان لېرې وساتئ او څه چې لرئ په هغو باندې قناعت وکړئ، ځکه چې خدای ویلي دي: «زه به هېڅکله تاسو یوازې پرېنږدم او هېڅکله به مو نه هېروم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_5.mp3', '', 1761754199, 1761754199),
(32676, 'Hebrews 13:6', 'Hebrews', 13, 6, 'نو مونږ په ډاډه زړه ویلی شو: زما مرستندوی دی څښتن نه به وېرېږمه زه څه کولای شي انسان ما سره؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_6.mp3', '', 1761754199, 1761754199),
