(32678, 'Hebrews 13:8', 'Hebrews', 13, 8, 'عیسی مسیح پرون، نن او د تل دپاره یوشان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_8.mp3', '', 1761754199, 1761754199),
(32679, 'Hebrews 13:9', 'Hebrews', 13, 9, 'د هر ډول عجیبه تعلیمونو له امله مه بې‌لارې کېږئ. دا ښه ده چې زمونږ زړونه د خدای په فضل باندې قوي شي، نه په مذهبي قوانینو پورې تړلي خوړو باندې، ځکه کوم خلک چې دا قانون په مخ وړي هېڅ ګټه ورته نه رسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_9.mp3', '', 1761754199, 1761754199),
(32680, 'Hebrews 13:10', 'Hebrews', 13, 10, 'مونږ داسې د قربانۍ ځای لرو چې حتی هغه کاهنان چې هلته په سپېڅلې خېمه کې خدمت کوي، د هغې قربانۍ د خوړلو حق نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_10.mp3', '', 1761754199, 1761754199),
(32681, 'Hebrews 13:11', 'Hebrews', 13, 11, 'ځکه چې لوی کاهن به د حیواناتو وینه د ګناه د قربانۍ په توګه ډېر سپېڅلي ځای ته وړله، خو د هغوی مړي د کمپ نه دباندې سوځول کېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_11.mp3', '', 1761754199, 1761754199),
(32682, 'Hebrews 13:12', 'Hebrews', 13, 12, 'نو له دې امله عیسی هم د ښار د دروازې نه دباندې کړاوونه وزغمل او مړ شو، ترڅو د خپلې وینې په وسیله خلک د ګناه څخه پاک کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_12.mp3', '', 1761754199, 1761754199),
