(32686, 'Hebrews 13:16', 'Hebrews', 13, 16, 'نېکي کول او د نورو سره مرسته کول مه هېروئ، ځکه چې خدای په داسې قربانیو خوشحالیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_16.mp3', '', 1761754199, 1761754199),
(32687, 'Hebrews 13:17', 'Hebrews', 13, 17, 'د خپلو مشرانو اطاعت کوئ او څه چې درته وایي هماغسې کوئ. هغوی په تاسو باندې پام کوي او خدای ته به حساب ورکوي. نو پرېږدئ چې هغوی دا کار په خوشحالۍ سره وکړي، نه په خفګان. که نه، نو تاسو ته به یې ګټه ونه رسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_17.mp3', '', 1761754199, 1761754199),
(32688, 'Hebrews 13:18', 'Hebrews', 13, 18, 'زمونږ دپاره دعا کوئ. مونږ ډاډمن یو چې زمونږ وجدان پاک دی او غواړو چې په هر لحاظ د عزت ژوند وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_18.mp3', '', 1761754199, 1761754199),
(32689, 'Hebrews 13:19', 'Hebrews', 13, 19, 'زه ستاسو نه په کلکه غوښتنه کوم چې دعا وکړئ، ترڅو ډېر زر بېرته تاسو ته راشم. وروستۍ دعاګانې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_19.mp3', '', 1761754199, 1761754199),
(32690, 'Hebrews 13:20', 'Hebrews', 13, 20, 'اوس دې د سولې او سلامتۍ خدای چې د تلپاتې لوظ د وینې په وسیله یې زمونږ څښتن عیسی چې لوی شپون دی، د مړو نه بېرته راژوندی کړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_20.mp3', '', 1761754199, 1761754199),
(32691, 'Hebrews 13:21', 'Hebrews', 13, 21, 'نو هغه دې د خپلې رضا پوره کولو دپاره په خپلو ټولو ښو کارونو کې تیار کړي او د عیسی مسیح په وسیله دې په مونږ کې هغه کارونه وکړي چې هغه پرې خوشحالیږي. د هغه جلال دې تل ترتله وي. امین. وروستني سلامونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_21.mp3', '', 1761754199, 1761754199),
(32692, 'Hebrews 13:22', 'Hebrews', 13, 22, 'ای خویندو او ورونو! ستاسو نه په کلکه غوښتنه کوم چې زما نصیحت په صبر او حوصلې سره واورئ، ځکه چې هغه مې درته په لنډ ډول لیکلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_22.mp3', '', 1761754199, 1761754199),
(32693, 'Hebrews 13:23', 'Hebrews', 13, 23, 'زه غواړم تاسو خبر شئ چې زمونږ ورور تیموتاوس د زندان نه خلاص شوی دی. که هغه زر دلته راشي، نو هغه به زما سره ستاسو لیدو ته درشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_23.mp3', '', 1761754199, 1761754199),
(32694, 'Hebrews 13:24', 'Hebrews', 13, 24, 'خپلو ټولو مشرانو او ایماندارانو ته زمونږ سلامونه ووایئ. د ایټالیې ایمانداران هم تاسو ته خپل سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_24.mp3', '', 1761754199, 1761754199),
(32695, 'Hebrews 13:25', 'Hebrews', 13, 25, 'په تاسو ټولو دې د خدای فضل وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews13_verse_25.mp3', '', 1761754199, 1761754199),
(32696, 'Mark 8:1', 'Mark', 8, 1, 'په هغو ورځو کې یوځل بیا ګڼ شمېر خلک راټول شول او د هغوی سره د خوړلو دپاره هېڅ شی نه ؤ، نو عیسی خپل شاګردان راوغوښتل او ورته ویې ویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_1.mp3', '', 1761754199, 1761754199),
(32697, 'Mark 8:2', 'Mark', 8, 2, '«په دې خلکو باندې زما زړه سوځي، ځکه چې درې ورځې کیږي هغوی زما سره دي او هېڅ شی ورسره نشته چې ویې خوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_2.mp3', '', 1761754199, 1761754199),
(32698, 'Mark 8:3', 'Mark', 8, 3, 'که چېرې هغوی خپلو کورونو ته وږي رخصت کړم نو په لاره کې به بې‌حاله شي، ځکه چې په هغوی کې ځینې یې د لېرې ځایونو څخه راغلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_3.mp3', '', 1761754199, 1761754199),
(32699, 'Mark 8:4', 'Mark', 8, 4, 'شاګردانو یې ځواب ورکړ: «په دې دښته کې څوک دومره خلکو ته ډوډۍ ورکولای شي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_4.mp3', '', 1761754199, 1761754199),
(32700, 'Mark 8:5', 'Mark', 8, 5, 'عیسی پوښتنه وکړه: «تاسو سره څو ډوډۍ دي؟» هغوی ځواب ورکړ: «اووه ډوډۍ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_5.mp3', '', 1761754199, 1761754199),
(32701, 'Mark 8:6', 'Mark', 8, 6, 'نو عیسی خلکو ته وویل چې په ځمکه کښېني. بیا یې هغه اووه ډوډۍ راواخیستلې، د خدای شکر یې وویست، ډوډۍ یې ماتې کړې او شاګردانو ته یې ورکړلې چې په خلکو باندې یې ووېشي او شاګردانو همداسې وکړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_6.mp3', '', 1761754199, 1761754199),
(32702, 'Mark 8:7', 'Mark', 8, 7, 'د هغوی سره یو څو واړه ماهیان هم وو. عیسی په هغو هم شکر وویست او شاګردانو ته یې وویل چې هغه هم ووېشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_7.mp3', '', 1761754199, 1761754199),
(32703, 'Mark 8:8', 'Mark', 8, 8, 'خلکو هغه وخوړل او ټول ورباندې ماړه شول او د ډوډۍ د پاتې شویو ټوټو نه اووه ټوکرۍ ډکې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_8.mp3', '', 1761754199, 1761754199),
(32704, 'Mark 8:9', 'Mark', 8, 9, 'په هغه ځای کې نژدې څلور زره کسان وو. عیسی هغوی رخصت کړل،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_9.mp3', '', 1761754199, 1761754199),
(32705, 'Mark 8:10', 'Mark', 8, 10, 'او سمدلاسه د خپلو شاګردانو سره په کشتۍ کې سپور شو او د دلمانوته سیمې ته لاړ. د فریسیانو له خوا د معجزې غوښتنه (متي ۱۶‏:‌۱‌‏-‌۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_10.mp3', '', 1761754199, 1761754199),
(32706, 'Mark 8:11', 'Mark', 8, 11, 'فریسیان راغلل او د عیسی سره یې بحث پیل کړ او د دې دپاره چې هغه وازمایي، نو د هغه څخه یې وغوښتل چې دوی ته یوه اسماني معجزه وښایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_11.mp3', '', 1761754199, 1761754199),
(32707, 'Mark 8:12', 'Mark', 8, 12, 'هغه یو سوړ اوسېلی وویست او ویې ویل: «د دې زمانې خلک ولې معجزه غواړي؟ په یقین سره زه تاسو ته دا وایم چې دې خلکو ته به هېڅ یوه معجزه ونه ښودل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_12.mp3', '', 1761754199, 1761754199),
(32708, 'Mark 8:13', 'Mark', 8, 13, 'بیا عیسی هغوی پرېښودل او بېرته په کشتۍ کې کښېناست او د بحیرې بلې غاړې ته لاړ. د فریسیانو او هیرودیس د تعلیم څخه لېرې اوسئ (متي ۱۶‏:‌۵‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_13.mp3', '', 1761754199, 1761754199),
(32709, 'Mark 8:14', 'Mark', 8, 14, 'شاګردانو دا هېر کړي وو چې د ځان سره ډوډۍ یوسي او په کشتۍ کې د هغوی سره یوازې یوه ډوډۍ وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_14.mp3', '', 1761754199, 1761754199),
(32710, 'Mark 8:15', 'Mark', 8, 15, 'عیسی هغوی ته امر وکړ او ویې ویل: «پام کوئ، د فریسیانو او هیرودیس د خمیرې نه به ځانونه ساتئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark8_verse_15.mp3', '', 1761754199, 1761754199);